create or replace function iam._ensure_tenant_default_store(p_tenant_id uuid)
returns uuid
language plpgsql
security definer
set search_path = iam, pg_temp
as $$
declare
  v_store_id uuid;
  v_tenant_name text;
begin
  if p_tenant_id is null then
    raise exception using errcode = 'P0001',
      message = '{"code":"CONTEXT_INVALID","message":"Tenant id is required.","details":{}}';
  end if;

  select s.id
  into v_store_id
  from iam.stores s
  where s.tenant_id = p_tenant_id
    and s.status = 'active'
    and s.code = 'default'
  limit 1;

  if v_store_id is null then
    select s.id
    into v_store_id
    from iam.stores s
    where s.tenant_id = p_tenant_id
      and s.status = 'active'
    order by s.created_at, s.id
    limit 1;
  end if;

  if v_store_id is null then
    select coalesce(nullif(trim(t.display_name), ''), 'Default Store')
    into v_tenant_name
    from iam.tenants t
    where t.id = p_tenant_id;

    if v_tenant_name is null then
      raise exception using errcode = 'P0001',
        message = '{"code":"RESOURCE_NOT_FOUND","message":"Tenant not found.","details":{}}';
    end if;

    insert into iam.stores (tenant_id, code, display_name, status)
    values (p_tenant_id, 'default', v_tenant_name, 'active')
    on conflict (tenant_id, code) do update
      set display_name = excluded.display_name,
          status = 'active'
    returning id into v_store_id;
  end if;

  return v_store_id;
end;
$$;


revoke all on function iam._ensure_tenant_default_store(uuid) from public, anon;
